using System.Linq;
using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Fibers;

internal sealed class FiveModeDensityFiberDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Full-rank five-mode density fibres and their affine coordinates.",
        H("Five-mode local density fibres"),
        Blocks(Describe.Lean(DescribeId.Create("full-rank-local-fibre"),
            DeclarationHandle.Create("D5/S3/Quantum/Fibers/FiveModeDensityFiber.full_rank_local_fibre"),
            H("The full-rank mean fibre has 21 real local dimensions"),
            StatementSource.FromAuthor(Disp(All("Rho",Call("ComplexMatrix",D(5),D(5)),Rel(Conj(Call("PosDef",F.Id("Rho")),Rel(Call("Trace",F.Id("Rho")),Eq,D(1))),Implies,Conj(Rel(Call("RealFinrank",Call("Kernel",Call("modeReadout"))),Eq,D(2,1)),All("Sigma",Call("ComplexMatrix",D(5),D(5)),Rel(Call("IsHermitian",F.Id("Sigma")),Implies,Rel(Conj(Rel(Call("Trace",F.Id("Sigma")),Eq,D(1)),Rel(Call("means",F.Id("Sigma")),Eq,Call("means",F.Id("Rho")))),Iff,Unique("h",Call("Kernel",Call("modeReadout")),Rel(F.Id("Sigma"),Eq,Call("fibrePoint",F.Id("Rho"),F.Id("h"))))))),Ex("epsilon",Call("Real"),Conj(Rel(D(0),Lt,F.Id("epsilon")),All("h",Call("Kernel",Call("modeReadout")),Rel(Rel(Call("CstarOperatorNorm",F.Id("h")),Lt,F.Id("epsilon")),Implies,Conj(Call("PosDef",Call("fibrePoint",F.Id("Rho"),F.Id("h"))),Rel(Call("Trace",Call("fibrePoint",F.Id("Rho"),F.Id("h"))),Eq,D(1)),Rel(Call("means",Call("fibrePoint",F.Id("Rho"),F.Id("h"))),Eq,Call("means",F.Id("Rho"))))))))))))), AssessedProvenance.FromRepo(),
            Blocks(
                Paragraph(Text("The ordered modes are empty, one, two, three, and thirteen. The three means, ordered X,Z,Y, are rho(1,1)+rho(4,4), rho(2,2), and rho(3,3)+rho(4,4), with real parts understood. Trace-zero Hermitian five-by-five matrices have real dimension 24, by BipartiteSectorDecomposition.trace_zero_hermitian_finrank. Explicit diagonal trace-zero matrices independently realize the three means, so the kernel has dimension 21.")),
                Paragraph(Text("For any positive-definite trace-one rho, every Hermitian matrix with trace one and the same means is uniquely rho+h with h in that kernel. Positive semidefiniteness is still a restriction on these affine coordinates. The real spectrum of rho has a strictly positive lower bound epsilon. A self-adjoint perturbation h satisfies minus its C-star operator norm times the identity <= h. Consequently every kernel perturbation with operator norm below epsilon remains positive definite, with unchanged trace and means. This gives an open 21-dimensional neighbourhood within the affine fibre at each full-rank point. The scalar identity divided by five is one such point. The conclusion does not impose the same dimension on lower-rank boundary fibres.")),
                Paragraph(Text("Writing kappa=rho(4,4), the diagonal probabilities are 1-X-Z-Y+kappa, X-kappa, Z, Y-kappa, and kappa. The single diagonal direction kappa is independent of the ten complex off-diagonal Hermitian coordinates, which supply twenty real directions. Positivity constrains both sets of coordinates jointly.")),
                Paragraph(Text("The pure states generated by (mode-one+mode-three)/sqrt(2) and (mode-one-mode-three)/sqrt(2) have X=Y=1/2, Z=kappa=0. They give expectations +1 and -1 for the self-adjoint observable C13=|one><three|+|three><one|. Thus three means do not determine this coherent readout. C13 is an observable with signed expectation; it is not a positive quantum effect. The empty mode is a nonzero basis vector. The probability-coordinate equalities and both positive trace-one coherence matrices are exact finite-matrix applications, rather than separately retained theorem wrappers."))),
            DescribeRole.Theorem))));

    private static Formula Call(string name, params Formula[] args) =>
        new Formula.FunctionCall(FormulaIdentifier.Create(name), [.. args]);
    private static Formula All(string name, Formula type, Formula body) =>
        Seq(Open, Forall, Sp, F.Id(name), Colon, Sp, type, Comma, Sp, body, Close);
    private static Formula Ex(string name, Formula type, Formula body) =>
        Seq(Open, Exists, Sp, F.Id(name), Colon, Sp, type, Comma, Sp, body, Close);
    private static Formula Unique(string name, Formula type, Formula body) =>
        Seq(Open, Exists, Sp, Bang, Sp, F.Id(name), Colon, Sp, type, Comma, Sp, body, Close);
    private static Formula Rel(Formula left, Formula relation, Formula right) =>
        Seq(Open, left, Sp, relation, Sp, right, Close);
    private static Formula Conj(params Formula[] statements) =>
        statements.Aggregate((left, right) => Rel(left, Land, right));
}
